(function(){function formatPrice(val){return "$"+Number(val).toFixed(2);}function initProductPage(){const mainSection=document.querySelector(".product-hero-section");if(!mainSection||typeof PRODUCTS==="undefined")return;const urlParams=new URLSearchParams(window.location.search);const productId=(urlParams.get("id")||"cyberpunk-2077").toLowerCase();const catalogList=typeof ALL_PRODUCTS!=="undefined"?ALL_PRODUCTS:PRODUCTS;const product=catalogList.find((p)=>p.id===productId)||PRODUCTS[0];document.title=`VEJIGAMES - ${product.title}: ${product.subtitle}`;const currentBreadcrumb=document.querySelector(".breadcrumb-current");if(currentBreadcrumb)currentBreadcrumb.textContent=product.title;const coverImg=document.querySelector(".product-cover-img");const coverTitle=document.querySelector(".product-cover-title");const coverSubtitle=document.querySelector(".product-cover-edition");const titleEl=document.querySelector(".product-title");const editionEl=document.querySelector(".product-edition");const descEl=document.querySelector(".product-description");const ratingEl=document.querySelector(".product-rating");const priceEl=document.querySelector(".product-price");const editionBadge=document.querySelector(".product-badge-edition");const languagesEl=document.querySelector(".product-languages-info");if(coverImg&&product.image){coverImg.src=product.image;coverImg.alt=`Portada de ${product.title}: ${product.subtitle}`;}if(coverTitle)coverTitle.textContent=product.title;if(coverSubtitle)coverSubtitle.textContent=product.subtitle;if(titleEl)titleEl.textContent=product.title;if(editionEl)editionEl.textContent=product.subtitle;if(descEl)descEl.textContent=product.description;if(priceEl)priceEl.textContent=formatPrice(product.price);if(editionBadge&&product.edition)editionBadge.textContent=product.edition;if(languagesEl&&product.compatibility)languagesEl.textContent=product.compatibility;if(ratingEl&&product.rating){ratingEl.innerHTML=`<span class="rating-star" aria-hidden="true">&#9733;</span> ${product.rating}`;}const buyBtn=document.querySelector(".btn-primary-buy");if(buyBtn){buyBtn.onclick=function(){if(window.NexoShop&&window.NexoShop.addToCart){window.NexoShop.addToCart(product.id);}};}const pillsContainer=document.querySelector(".product-spec-pills");if(pillsContainer){pillsContainer.innerHTML=`
        <span class="spec-pill">${product.platform || "PC / Windows"}</span>
        <span class="spec-pill">${product.genreFull || product.genre}</span>
        <span class="spec-pill">PEGI ${product.pegi}</span>
        <span class="spec-pill">1 jugador</span>
      `;}const dlcSection=document.querySelector(".product-dlc-section");const dlcList=document.querySelector(".dlc-items-list");if(dlcSection&&dlcList){if(product.dlcs&&product.dlcs.length>0){dlcSection.style.display="";dlcList.innerHTML=product.dlcs
.map((dlc)=>`
          <article class="dlc-card">
            <div class="dlc-card-left">
              <div class="dlc-thumb-badge" aria-hidden="true">
                ${dlc.image ? `<img src="${dlc.image}" alt="${dlc.title}" class="dlc-badge-img" loading="lazy" decoding="async"/>` : `<span>${dlc.icon||"☉"}</span>`}
              </div>
              <div class="dlc-card-info">
                <h3 class="dlc-title">${dlc.title}</h3>
                <p class="dlc-description">${dlc.description}</p>
              </div>
            </div>
            <div class="dlc-card-right">
              <span class="dlc-price">${formatPrice(dlc.price)}</span>
              <button type="button" class="btn-dlc-add" onclick="window.NexoShop && window.NexoShop.addToCart('${product.id}', true)">
                Agregar
              </button>
            </div>
          </article>
        `).join("");}else{dlcSection.style.display="none";}}if(product.requirements){const minCard=document.querySelector(".requirements-card:first-child .requirements-spec-list");const recCard=document.querySelector(".requirements-card:last-child .requirements-spec-list");function buildReqList(reqObj){if(!reqObj)return "";return Object.entries(reqObj).map(([k,v])=>`
            <div class="req-spec-row">
              <dt class="req-label">${k.charAt(0).toUpperCase() + k.slice(1)}</dt>
              <dd class="req-value">${v}</dd>
            </div>
          `).join("");}if(minCard&&product.requirements.minimum){minCard.innerHTML=buildReqList(product.requirements.minimum);}if(recCard&&product.requirements.recommended){recCard.innerHTML=buildReqList(product.requirements.recommended);}}}window.initProductPage=initProductPage;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initProductPage);}else{initProductPage();}})();